import { VixSrcClient } from './VixSrcClient';

// Esempio di utilizzo del client VixSrc
const client = new VixSrcClient();

// Configurazione per un film
const movieConfig = {
  tmdbId: 786892, // ID del film da TMDB
  primaryColor: 'B20710',
  secondaryColor: '170000',
  autoplay: false,
  lang: 'it'
};

// Configurazione per una serie TV
const tvConfig = {
  tmdbId: 1399, // ID della serie da TMDB
  season: 1,
  episode: 1,
  primaryColor: 'B20710',
  autoplay: true,
  lang: 'it'
};

// Funzione per inizializzare il player quando il DOM è pronto
function initializePlayer() {
  console.log('Inizializzazione VixSrc Player...');

  try {
    // Embed di un film
    const movieIframe = client.embed(movieConfig, {
      container: '#movie-container',
      width: '100%',
      height: '500px'
    });

    // Embed di una serie TV
    const tvIframe = client.embed(tvConfig, {
      container: '#tv-container', 
      width: '100%',
      height: '500px'
    });

    // Aggiungi listener per gli eventi del player
    client.addEventListener('play', (event) => {
      console.log('Video started playing:', event.data);
    });

    client.addEventListener('pause', (event) => {
      console.log('Video paused:', event.data);
    });

    client.addEventListener('ended', (event) => {
      console.log('Video ended:', event.data);
    });

    client.addEventListener('timeupdate', (event) => {
      // Uncomment per vedere tutti gli aggiornamenti del tempo
      // console.log('Time update:', event.data.currentTime);
    });

    console.log('Player inizializzato con successo!');

  } catch (error) {
    console.error('Errore durante l\'inizializzazione:', error);
  }
}

// Funzione per testare l'API del catalogo
async function loadCatalog() {
  try {
    console.log('Caricamento catalogo film...');
    const movieCatalog = await client.fetchCatalog('movie', 'it');
    console.log('Catalogo film:', movieCatalog);

    console.log('Caricamento catalogo serie TV...');
    const tvCatalog = await client.fetchCatalog('tv', 'it');
    console.log('Catalogo TV:', tvCatalog);

  } catch (error) {
    console.error('Errore nel caricamento del catalogo:', error);
  }
}

// Inizializza quando il DOM è pronto
if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initializePlayer);
  } else {
    initializePlayer();
  }

  // Carica il catalogo
  loadCatalog();
}

// Esporta per uso in altri moduli
export { VixSrcClient } from './VixSrcClient';
export * from './types/vixsrc';